"use strict";const MISE=50;const RED_NUMBERS=new Set([1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36]);const SPIN_DURATION_MS=3500;let choix=null;let isSpinning=false;const betBtns=document.querySelectorAll(".bet-btn");const btnJouer=document.getElementById("btn-jouer");const btnReset=document.getElementById("btn-reset");const resultBanner=document.getElementById("result-banner");const rouletteRes=document.getElementById("roulette-result");const rouletteWrapper=document.getElementById("roulette-wrapper");const rouletteWheel=document.getElementById("roulette-wheel");const numeroTire=document.getElementById("numero-tire");const couleurTire=document.getElementById("couleur-tire");const soldeDisplay=document.getElementById("solde-display");let currentRotation=0;function setBetControlsDisabled(disabled){betBtns.forEach(btn=>{btn.disabled=disabled;});}
const wheelNums=[0,32,15,19,4,21,2,25,17,34,6,27,13,36,11,30,8,23,10,5,24,16,33,1,20,14,31,9,22,18,29,7,28,12,35,3,26];const sliceAngle=360/37;function getRouletteColor(num){if(num===0)return"vert";return RED_NUMBERS.has(num)?"rouge":"noir";}
let svgHTML=`<svg viewBox="-100 -100 200 200" xmlns="http://www.w3.org/2000/svg">`;for(let i=0;i<37;i++){const rot=i*sliceAngle;const a1=-sliceAngle/2*Math.PI/180;const a2=sliceAngle/2*Math.PI/180;const x1=100*Math.sin(a1),y1=-100*Math.cos(a1);const x2=100*Math.sin(a2),y2=-100*Math.cos(a2);const num=wheelNums[i];const couleur=getRouletteColor(num);let fill="#1a1a1a";if(couleur==="rouge")fill="#c0392b";if(couleur==="vert")fill="#27ae60";svgHTML+=`
    <g transform="rotate(${rot})">
      <path d="M 0 0 L ${x1} ${y1} A 100 100 0 0 1 ${x2} ${y2} Z" fill="${fill}" stroke="#fff" stroke-width="0.3" />
      <text x="0" y="-84" fill="#fff" font-size="8" font-weight="bold" font-family="sans-serif" text-anchor="middle" transform="rotate(0, 0, -84)">${wheelNums[i]}</text>
    </g>
  `;}
svgHTML+=`
  <circle cx="0" cy="0" r="60" fill="#222" stroke="#444" stroke-width="2"/>
  <text x="0" y="4" fill="#666" font-size="12" font-weight="bold" font-family="sans-serif" text-anchor="middle">GreenBet</text>
</svg>`;if(rouletteWheel)rouletteWheel.innerHTML=svgHTML;betBtns.forEach(btn=>{const value=btn.dataset.choix;if(value==="rouge")btn.classList.add("rouge-btn");else if(value==="noir")btn.classList.add("noir-btn");else{const num=Number(value);const color=getRouletteColor(num);if(color==="rouge")btn.classList.add("num-rouge-btn");else if(color==="noir")btn.classList.add("num-noir-btn");else btn.classList.add("vert-btn");}
btn.addEventListener("click",()=>{if(isSpinning)return;betBtns.forEach(b=>b.classList.remove("selected"));btn.classList.add("selected");choix=btn.dataset.choix;btnJouer.disabled=false;});});btnReset.addEventListener("click",()=>{if(isSpinning)return;choix=null;betBtns.forEach(b=>b.classList.remove("selected"));setBetControlsDisabled(false);btnJouer.disabled=true;resultBanner.className="result-banner";resultBanner.textContent="";rouletteRes.style.display="none";rouletteWrapper.style.display="none";});btnJouer.addEventListener("click",()=>{if(!choix||isSpinning)return;isSpinning=true;btnJouer.disabled=true;btnReset.disabled=true;setBetControlsDisabled(true);resultBanner.className="result-banner";resultBanner.textContent="";rouletteRes.style.display="none";fetch("/api/roulette/jouer",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({mise:MISE,choix}),}).then(r=>r.json()).then(data=>{if(data.error){showResult("perdu",data.error);return;}
rouletteWrapper.style.display="block";const drawnNum=data.numero;const idx=wheelNums.indexOf(drawnNum);let targetAngle=360-(idx*sliceAngle);targetAngle+=(Math.random()-0.5)*(sliceAngle*0.8);const diff=targetAngle-(currentRotation%360);let diffToAdd=diff;if(diffToAdd<0)diffToAdd+=360;const spins=5*360;const nextRotation=currentRotation+spins+diffToAdd;rouletteWheel.style.transition="none";rouletteWheel.style.transform=`rotate(${currentRotation}deg)`;rouletteWheel.getBoundingClientRect();rouletteWheel.style.transition="transform 3.5s cubic-bezier(0.2, 0.8, 0.2, 1)";requestAnimationFrame(()=>{rouletteWheel.style.transform=`rotate(${nextRotation}deg)`;});currentRotation=nextRotation;setTimeout(()=>{numeroTire.textContent=data.numero;couleurTire.className="badge";if(data.couleur==="rouge"){couleurTire.textContent="Rouge";couleurTire.className+=" badge-red";}else if(data.couleur==="vert"){couleurTire.textContent="Vert (0)";couleurTire.className+=" badge-green";}else{couleurTire.textContent="Noir";couleurTire.className+=" badge-dark";}
rouletteRes.style.display="block";const sign=data.points>=0?"+":"";if(data.resultat==="gagne"){showResult("gagne",`Gagné ! ${sign}${data.points} pts`);}else{showResult("perdu",`Perdu. ${sign}${data.points} pts`);}
if(data.new_solde!==undefined&&soldeDisplay){soldeDisplay.textContent=data.new_solde;}
const soldeNav=document.getElementById("solde-nav");if(data.new_solde!==undefined&&soldeNav){soldeNav.textContent=`${data.new_solde} pts`;}
isSpinning=false;setBetControlsDisabled(false);btnReset.disabled=false;btnJouer.disabled=false;},SPIN_DURATION_MS+50);}).catch(()=>{showResult("perdu","Erreur réseau. Êtes-vous connecté ?");isSpinning=false;setBetControlsDisabled(false);btnReset.disabled=false;btnJouer.disabled=false;});});function showResult(cls,msg){resultBanner.className=`result-banner ${cls} show`;resultBanner.textContent=msg;}